  // f:         Input normalized distribution functions [F, G]. 
  // out:       Incremented output [F, G]. 
  // Returns the CFL frequency estimate of the closure rates. 
  const double dv1 = 2.0/dxv[1]; 
  const double dvpar = dxv[1], wvpar = w[1]; 
  const double *F_0 = &f[0]; 
  const double *G_1 = &f[6]; 
  double *out_F_0 = &out[0]; 
  double *out_G_1 = &out[6]; 
 
  out_F_0[0] += 0.7071067811865475*F_0[1]*c_0[1]+0.7071067811865475*F_0[0]*c_0[0]; 
  out_F_0[1] += 0.7071067811865475*F_0[0]*c_0[1]+0.7071067811865475*c_0[0]*F_0[1]; 
  out_F_0[2] += (1.224744871391589*F_0[1]*c_h[1]+1.224744871391589*F_0[0]*c_h[0])*dv1*wvpar+(0.3535533905932737*c_h[1]*F_0[3]+0.3535533905932737*c_h[0]*F_0[2])*dv1*dvpar+(1.224744871391589*F_0[1]*alpha_0[1]+1.224744871391589*F_0[0]*alpha_0[0])*dv1+0.7071067811865475*c_0[1]*F_0[3]+0.7071067811865475*c_0[0]*F_0[2]; 
  out_F_0[3] += (1.224744871391589*F_0[0]*c_h[1]+1.224744871391589*c_h[0]*F_0[1])*dv1*wvpar+(0.3535533905932737*c_h[0]*F_0[3]+0.3535533905932737*c_h[1]*F_0[2])*dv1*dvpar+(1.224744871391589*F_0[0]*alpha_0[1]+1.224744871391589*alpha_0[0]*F_0[1])*dv1+0.7071067811865475*c_0[0]*F_0[3]+0.7071067811865475*c_0[1]*F_0[2]; 
  out_F_0[4] += (2.7386127875258306*c_h[1]*F_0[3]+2.7386127875258306*c_h[0]*F_0[2])*dv1*wvpar+(0.7071067811865475*c_h[1]*F_0[5]+0.7071067811865475*c_h[0]*F_0[4]+0.7905694150420947*F_0[1]*c_h[1]+0.7905694150420947*F_0[0]*c_h[0])*dv1*dvpar+(2.7386127875258306*alpha_0[1]*F_0[3]+2.7386127875258306*alpha_0[0]*F_0[2])*dv1+0.7071067811865475*c_0[1]*F_0[5]+0.7071067811865475*c_0[0]*F_0[4]; 
  out_F_0[5] += (2.7386127875258306*c_h[0]*F_0[3]+2.7386127875258306*c_h[1]*F_0[2])*dv1*wvpar+(0.7071067811865475*c_h[0]*F_0[5]+0.7071067811865475*c_h[1]*F_0[4]+0.7905694150420948*F_0[0]*c_h[1]+0.7905694150420948*c_h[0]*F_0[1])*dv1*dvpar+(2.7386127875258306*alpha_0[0]*F_0[3]+2.7386127875258306*alpha_0[1]*F_0[2])*dv1+0.7071067811865475*c_0[0]*F_0[5]+0.7071067811865475*c_0[1]*F_0[4]; 
  out_G_1[0] += 1.4142135623730951*G_1[1]*c_h[1]+0.7071067811865475*G_1[1]*c_0[1]+1.4142135623730951*G_1[0]*c_h[0]+0.7071067811865475*G_1[0]*c_0[0]; 
  out_G_1[1] += 1.4142135623730951*G_1[0]*c_h[1]+0.7071067811865475*G_1[0]*c_0[1]+1.4142135623730951*c_h[0]*G_1[1]+0.7071067811865475*c_0[0]*G_1[1]; 
  out_G_1[2] += (1.224744871391589*G_1[1]*c_h[1]+1.224744871391589*G_1[0]*c_h[0])*dv1*wvpar+(0.3535533905932737*c_h[1]*G_1[3]+0.3535533905932737*c_h[0]*G_1[2])*dv1*dvpar+(1.224744871391589*G_1[1]*alpha_0[1]+1.224744871391589*G_1[0]*alpha_0[0])*dv1+1.4142135623730951*c_h[1]*G_1[3]+0.7071067811865475*c_0[1]*G_1[3]+1.4142135623730951*c_h[0]*G_1[2]+0.7071067811865475*c_0[0]*G_1[2]; 
  out_G_1[3] += (1.224744871391589*G_1[0]*c_h[1]+1.224744871391589*c_h[0]*G_1[1])*dv1*wvpar+(0.3535533905932737*c_h[0]*G_1[3]+0.3535533905932737*c_h[1]*G_1[2])*dv1*dvpar+(1.224744871391589*G_1[0]*alpha_0[1]+1.224744871391589*alpha_0[0]*G_1[1])*dv1+1.4142135623730951*c_h[0]*G_1[3]+0.7071067811865475*c_0[0]*G_1[3]+1.4142135623730951*c_h[1]*G_1[2]+0.7071067811865475*c_0[1]*G_1[2]; 
  out_G_1[4] += (2.7386127875258306*c_h[1]*G_1[3]+2.7386127875258306*c_h[0]*G_1[2])*dv1*wvpar+(0.7071067811865475*c_h[1]*G_1[5]+0.7071067811865475*c_h[0]*G_1[4]+0.7905694150420947*G_1[1]*c_h[1]+0.7905694150420947*G_1[0]*c_h[0])*dv1*dvpar+(2.7386127875258306*alpha_0[1]*G_1[3]+2.7386127875258306*alpha_0[0]*G_1[2])*dv1+1.4142135623730951*c_h[1]*G_1[5]+0.7071067811865475*c_0[1]*G_1[5]+1.4142135623730951*c_h[0]*G_1[4]+0.7071067811865475*c_0[0]*G_1[4]; 
  out_G_1[5] += (2.7386127875258306*c_h[0]*G_1[3]+2.7386127875258306*c_h[1]*G_1[2])*dv1*wvpar+(0.7071067811865475*c_h[0]*G_1[5]+0.7071067811865475*c_h[1]*G_1[4]+0.7905694150420948*G_1[0]*c_h[1]+0.7905694150420948*c_h[0]*G_1[1])*dv1*dvpar+(2.7386127875258306*alpha_0[0]*G_1[3]+2.7386127875258306*alpha_0[1]*G_1[2])*dv1+1.4142135623730951*c_h[0]*G_1[5]+0.7071067811865475*c_0[0]*G_1[5]+1.4142135623730951*c_h[1]*G_1[4]+0.7071067811865475*c_0[1]*G_1[4]; 
 
  return fabs(0.7071067811865475*c_0[0]) + 2.0*fabs(0.7071067811865475*c_h[0]); 
